"use strict";
const state = {user:null,csrf:"",ai:{provider:"local"},sprint:2,view:"home",register:false,university:{},departments:[],requests:[],notifications:[],staffUnread:0,staffReady:false,models:null,alerts:[],supervisor:[],alertError:false,filters:{status:"",department:"",priority:"",open:true}};
const root=document.getElementById("app");
let knownAlerts=new Set(),alertsUser=null;
const ageText=s=>s<60?`${s}s ago`:`${Math.floor(s/60)} min ago`;
const dialog=document.getElementById("request-dialog");
const esc=value=>String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
const date=value=>new Date(value).toLocaleString(undefined,{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"});
const badge=r=>`<span class="pill ${esc(r.status.replaceAll(" ","-"))}">${esc(r.status)}</span>${r.priority==="urgent"?'<span class="pill urgent">Urgent</span>':""}${msgBadge(r)}`;
const departmentOptions=(selected="")=>state.departments.map(d=>`<option value="${esc(d.code)}" ${d.code===selected?"selected":""}>${esc(d.name)}</option>`).join("");
let toastTimer;
function toast(message){const box=document.getElementById("toast");box.textContent=message;box.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.hidden=true,5000);}
async function api(path,method="GET",data){const options={method,credentials:"same-origin",headers:{}};if(data!==undefined){options.headers={"Content-Type":"application/json","X-CSRF-Token":state.csrf};options.body=JSON.stringify(data);}const res=await fetch(path,options);const result=await res.json();if(!res.ok){if(res.status===401&&state.user){state.user=null;renderAuth();}throw new Error(result.error||"The request failed.");}return result;}
function aiLabel(ai=state.ai){if(ai.provider!=="gemini")return "Local ML · offline";if(!ai.configured)return "Gemini · key required";if(ai.last_error)return "Gemini · staff review fallback";return `Gemini · ${ai.model}${ai.connection_verified?" · response verified":" · configured"}`;}
function aiDescription(ai=state.ai){if(ai.provider!=="gemini")return "The local model classifies English requests. Other languages are preserved for staff review.";if(!ai.configured)return "Gemini is selected but has no server API key. Requests will be saved for staff review.";if(ai.last_error)return "Gemini is currently unavailable. Your request will be saved for a support officer.";return "Gemini analyzes the meaning of your request and suggests the right department. Unclear requests go to staff.";}
function aiBanner(){return `<div class="ai-banner"><strong class="ai-mode" data-testid="ai-mode">${esc(aiLabel())}</strong><span>${esc(aiDescription())}</span></div>`;}
function studentIdentity(){const p=state.user?.student_profile;if(!p)return "";return `<section class="student-profile" aria-label="Student profile"><strong>${esc(state.user.email)}</strong><span>Admission ${p.admission_year}</span><span data-testid="student-course">Year ${p.course} · ${esc(p.academic_year)}</span></section>`;}
function updateStudentEmailHint(){const field=document.getElementById("email");const hint=document.getElementById("student-email-hint");if(!field||!hint)return;const email=field.value.trim().toLowerCase();const match=/^([0-9]{2})[0-9]{7}@sdu[.]edu[.]kz$/.exec(email);if(!match){hint.textContent="Only SDU student accounts: 9 digits followed by @sdu.edu.kz.";return;}const admission=2000+Number(match[1]);const start=state.university.academic_year_start;hint.textContent=admission>start?"Admission year cannot be later than the current academic year.":`Admission ${admission} · Year ${start-admission+1} · ${state.university.academic_year}`;}
document.addEventListener("input",event=>{if(state.register&&event.target.id==="email")updateStudentEmailHint();});
function renderAuth(){state.animView=null;root.innerHTML=`<div class="auth${state.authSeen?"":" intro"}"><section class="auth-story">${authArt()}<div class="brand"><img src="/logo.svg" alt="">Campus Route</div><div><div class="eyebrow">Student support, connected</div><h1><span class="hl"><span>The right help.</span></span><br><span class="hl"><span>One place to ask.</span></span></h1><p class="lead">Send your question. We’ll connect it to the right campus department and keep you updated.</p><div class="ticker" aria-hidden="true"><span class="tk-dot"></span><span class="tk-q"></span><span class="tk-arrow">→</span><span class="tk-dept"></span></div><div class="auth-steps"><div class="step"><div class="step-top"><div class="num">01</div><svg class="step-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M13 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V9z"/><path d="M13 3v6h6"/><path d="M8.5 13h4M8.5 17h3"/><path d="M15.5 17.5l4.2-4.2 1.3 1.3-4.2 4.2-1.8.5z"/></svg></div><p>Tell us what you need</p></div><div class="step"><div class="step-top"><div class="num">02</div><svg class="step-icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="9" cy="8" r="3.5"/><path d="M3 20v-1.2A4.3 4.3 0 0 1 7.3 14.5h3.4A4.3 4.3 0 0 1 15 18.8V20"/><path d="M16 4.7a3.5 3.5 0 0 1 0 6.6"/><path d="M18.5 14.9A4.3 4.3 0 0 1 21.5 18.8V20"/></svg></div><p>Reach the right team</p></div><div class="step"><div class="step-top"><div class="num">03</div><svg class="step-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 4v16h16"/><path d="M8 15l3.5-4 3 2.5L20 7"/><path d="M15.5 7H20v4.5"/></svg></div><p>Follow your request</p></div></div></div><footer class="small-text muted">AI Student Request Routing and Support System<br>INF 451 · Sprint ${state.sprint}<br><span class="ai-mode">${esc(aiLabel())}</span></footer></section><section class="auth-form-wrap"><div class="auth-form"><div class="eyebrow">Campus support portal</div><h2>${state.register?"Create your account":"Welcome back"}</h2><p class="muted">${state.register?"Use your SDU student email to request support.":"Sign in to send a request or support your students."}</p><form id="auth-form">${state.register?'<div class="field"><label for="name">Full name</label><input id="name" name="name" autocomplete="name" required minlength="2" maxlength="80"></div>':""}<div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="username" required maxlength="254" placeholder="240103030@sdu.edu.kz" ${state.register?'pattern="[0-9]{9}@[sS][dD][uU][.][eE][dD][uU][.][kK][zZ]" title="9-digit student ID followed by @sdu.edu.kz" aria-describedby="student-email-hint"':""}>${state.register?'<div id="student-email-hint" class="email-hint" role="status" aria-live="polite">Only SDU student accounts: 9 digits followed by @sdu.edu.kz.</div>':""}</div><div class="field"><label for="password">Password</label><div class="pw-wrap"><input id="password" name="password" type="password" autocomplete="${state.register?"new-password":"current-password"}" required ${state.register?'minlength="10"':""} maxlength="128" placeholder="${state.register?"At least 10 characters":"Your password"}"><button class="pw-toggle" type="button" data-pw-toggle aria-label="Show password" title="Show password">${ic("eye")}</button></div></div><div id="auth-error" class="error" role="alert" hidden></div><button class="btn btn-go" type="submit"><span>${state.register?"Create account":"Sign in"}</span>${ic("arrow")}</button></form><p class="auth-toggle">${state.register?"Already have an account?":"New here?"} <button class="text-btn" data-action="toggle-auth">${state.register?"Sign in":"Create an account"}</button></p><div class="demo-hint">For the classroom demonstration, use the accounts listed in the README. Contact your administrator for a staff account.</div></div></section></div>`;state.authSeen=true;startTicker();}
const ICONS={
inbox:'<path d="M22 12h-6l-2 3h-4l-2-3H2"/><path d="M5.5 5.1 2 12v6a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2v-6l-3.5-6.9A2 2 0 0 0 16.8 4H7.2a2 2 0 0 0-1.7 1.1z"/>',
bell:'<path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9"/><path d="M10.3 21a1.94 1.94 0 0 0 3.4 0"/>',
list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>',
sliders:'<path d="M4 21v-7M4 10V3M12 21v-9M12 8V3M20 21v-5M20 12V3M1 14h6M9 8h6M17 16h6"/>',
clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
check:'<circle cx="12" cy="12" r="9"/><path d="m8.5 12.5 2.5 2.5 4.5-5"/>',
eye:'<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',
alert:'<path d="M10.3 3.9 2.4 18a2 2 0 0 0 1.7 3h15.8a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z"/><path d="M12 9v4M12 17h.01"/>',
arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',
eyeoff:'<path d="M3 3l18 18"/><path d="M10.6 5.1A9.7 9.7 0 0 1 12 5c6.5 0 10 7 10 7a17 17 0 0 1-3.2 4M6.5 6.6C3.7 8.4 2 12 2 12s3.5 7 10 7a9.6 9.6 0 0 0 4.2-1"/><path d="M9.9 9.9a3 3 0 0 0 4.2 4.2"/>',
panel:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M9 4v16"/>',
cpu:'<rect x="5" y="5" width="14" height="14" rx="2"/><rect x="9" y="9" width="6" height="6"/><path d="M9 2v3M15 2v3M9 19v3M15 19v3M2 9h3M2 15h3M19 9h3M19 15h3"/>'
};
function ic(name,cls=""){return `<svg class="ic ${cls}" viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||""}</svg>`;}
function isCollapsed(){if(state.navCollapsed===undefined){try{state.navCollapsed=localStorage.getItem("cr-nav")==="1";}catch{state.navCollapsed=false;}}return state.navCollapsed;}
function emptyRequests(){return '<div class="empty empty-art"><svg class="empty-svg" viewBox="0 0 240 110" aria-hidden="true"><path class="route-line" d="M50 62C90 62 90 30 130 30S170 62 200 62" fill="none"/><circle class="route-node n1" cx="130" cy="30" r="6"/><circle class="route-node n2" cx="200" cy="62" r="6"/><circle class="route-node n3" cx="130" cy="88" r="6"/><path class="route-line" d="M50 62C90 62 90 88 130 88" fill="none"/><g class="float-env"><rect x="22" y="46" width="40" height="30" rx="7"/><path d="m24 50 18 13 18-13" fill="none"/></g></svg><strong>No requests yet</strong>Your requests will appear here after you send one.</div>';}
function emptyNotifications(){return '<div class="empty empty-art"><svg class="empty-svg small" viewBox="0 0 120 90" aria-hidden="true"><circle class="ring r1" cx="60" cy="45" r="16"/><circle class="ring r2" cx="60" cy="45" r="16"/><g class="bell-swing" transform="translate(48 33)"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#245e51" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'+ICONS.bell+'</svg></g></svg><strong>You’re all caught up</strong>Request confirmations will appear here.</div>';}
function decorate(content,animate){const sets={home:["inbox","clock","check"],queue:["list","eye","alert"],models:["cpu","check","list"]};const stats=content.querySelectorAll(".stat");(sets[state.view]||[]).forEach((n,i)=>{const stat=stats[i];if(stat&&!stat.querySelector(".stat-icon"))stat.insertAdjacentHTML("afterbegin",`<span class="stat-icon">${ic(n)}</span>`);});if(animate&&!matchMedia("(prefers-reduced-motion: reduce)").matches){content.querySelectorAll(".stat-value").forEach(el=>{const to=parseInt(el.textContent,10);if(!(to>0))return;const t0=performance.now();const tick=t=>{const p=Math.min(1,(t-t0)/700);el.textContent=Math.round(to*(1-Math.pow(1-p,3)));if(p<1)requestAnimationFrame(tick);};el.textContent="0";requestAnimationFrame(tick);});}}
document.addEventListener("click",event=>{const b=event.target.closest('[data-action="toggle-sidebar"]');if(!b)return;state.navCollapsed=!isCollapsed();try{localStorage.setItem("cr-nav",state.navCollapsed?"1":"0");}catch{}const w=document.querySelector(".workspace");if(w)w.classList.toggle("collapsed",state.navCollapsed);const label=(state.navCollapsed?"Expand":"Collapse")+" sidebar";b.setAttribute("aria-expanded",String(!state.navCollapsed));b.setAttribute("aria-label",label);b.title=label;});
function authArt(){return '<svg class="auth-art" viewBox="0 0 600 700" preserveAspectRatio="xMaxYMid slice" aria-hidden="true"><g class="art-rings"><circle cx="560" cy="120" r="70"/><circle cx="560" cy="120" r="130"/><circle cx="560" cy="120" r="190"/><circle cx="560" cy="120" r="250"/></g><path id="art-route" class="art-route" d="M300 705C300 625 340 566 400 560S500 625 530 545 580 430 580 360"/><g class="art-node"><circle cx="400" cy="560" r="7"/><circle cx="530" cy="545" r="7"/><circle cx="580" cy="360" r="7"/></g><circle class="art-packet" r="6"><animateMotion dur="7s" repeatCount="indefinite" rotate="auto"><mpath href="#art-route"/></animateMotion></circle><circle class="art-packet-glow" r="14"><animateMotion dur="7s" repeatCount="indefinite"><mpath href="#art-route"/></animateMotion></circle></svg>';}
const TICKS=[["“My Wi-Fi keeps dropping”","IT Helpdesk"],["“Where is my scholarship payment?”","Financial Aid"],["“I need to change my course schedule”","Academic Advising"],["“I need a medical certificate”","Health Services"]];
let tickTimer=null;
function startTicker(){clearInterval(tickTimer);const box=document.querySelector(".ticker");if(!box)return;const q=box.querySelector(".tk-q"),d=box.querySelector(".tk-dept");let i=0;const show=()=>{[q.textContent,d.textContent]=TICKS[i%TICKS.length];box.classList.remove("swap");void box.offsetWidth;box.classList.add("swap");i++;};show();tickTimer=setInterval(()=>{if(!document.querySelector(".ticker")){clearInterval(tickTimer);return;}show();},3600);}
function routeIntro(user,isNew){const role=user.role;const dest=role==="student"?(state.sprint===2?"My requests":"Request support"):role==="support"?"Support queue":"Routing settings";const first=esc((user.name||"").split(" ")[0]||"there");const el=document.createElement("div");el.className="route-intro";el.setAttribute("role","status");el.setAttribute("aria-live","polite");el.innerHTML=`<div class="ri-glow"></div><div class="ri-center"><div class="ri-logo"><span class="ri-ring"></span><span class="ri-ring r2"></span><img src="/logo.svg" alt=""></div><h2 class="ri-title">${isNew?"Welcome":"Welcome back"}, ${first}</h2><p class="ri-sub">Routing you to <strong>${esc(dest)}</strong></p><div class="ri-track" aria-hidden="true"><span class="ri-stop s1"></span><span class="ri-stop s2"></span><span class="ri-stop s3"></span><span class="ri-line"><i></i></span><span class="ri-packet"></span></div></div>`;document.body.appendChild(el);state.authSeen=false;const reduce=matchMedia("(prefers-reduced-motion: reduce)").matches;const ready=new Promise(r=>setTimeout(r,reduce?150:1900));return{ready,leave(abort){const go=()=>{el.classList.add("leaving");setTimeout(()=>el.remove(),abort?10:700);};go();}};}
document.addEventListener("click",event=>{const b=event.target.closest("[data-pw-toggle]");if(!b)return;const input=b.parentElement.querySelector("input");const show=input.type==="password";input.type=show?"text":"password";b.innerHTML=ic(show?"eyeoff":"eye");b.setAttribute("aria-label",show?"Hide password":"Show password");b.title=show?"Hide password":"Show password";});
function navItems(){if(state.user.role==="student")return[{id:"home",icon:"inbox",text:state.sprint===2?"My requests":"Request support"},{id:"notifications",icon:"bell",text:"Notifications",count:state.notifications.filter(n=>!n.read_at).length}];if(state.user.role==="support")return[{id:"queue",icon:"list",text:"Support queue",count:state.staffUnread}];return[{id:"settings",icon:"sliders",text:"Routing settings"},{id:"models",icon:"cpu",text:"Model retraining"}];}
function renderShell(){const navigation=navItems();root.innerHTML=`<div class="workspace${isCollapsed()?" collapsed":""}"><aside class="sidebar" id="sidebar"><div class="brand"><img src="/logo.svg" alt=""><span class="brand-text">Campus Route</span></div><nav aria-label="Main navigation">${navigation.map(n=>`<a class="nav-link ${state.view===n.id?"active":""}" href="${n.id==="queue"?"/staff":n.id==="home"?"/":"/"+n.id}" data-view="${n.id}" title="${esc(n.text)}">${ic(n.icon,"nav-icon")}<span class="nav-text">${esc(n.text)}</span>${n.count?`<span class="nav-number">${n.count}</span>`:""}</a>`).join("")}</nav><div class="sidebar-bottom"><span class="sb-text">Your question starts here.<br>Our teams take it from there.</span></div></aside><div class="content-wrap"><header class="topbar"><div class="topbar-left"><button class="nav-toggle" type="button" data-action="toggle-sidebar" aria-controls="sidebar" aria-expanded="${!isCollapsed()}" aria-label="${isCollapsed()?"Expand":"Collapse"} sidebar" title="${isCollapsed()?"Expand":"Collapse"} sidebar">${ic("panel")}</button><span>AI Student Request Routing and Support System</span></div><div class="account"><div class="avatar" aria-hidden="true">${esc(state.user.name.slice(0,1).toUpperCase())}</div><div><div class="account-name">${esc(state.user.name)}</div><div class="role">${esc(state.user.student_profile?`Student · Year ${state.user.student_profile.course}`:state.user.role)}</div></div><button class="sign-out" data-action="logout">Sign out</button></div></header><div id="alert-region" class="alert-region" role="alert" aria-live="assertive"></div><main id="content" class="content"></main></div></div>`;renderView();renderAlerts();if(state.user.role!=="student")pollAlerts();}
function renderView(){const content=document.getElementById("content");if(!content)return;const animate=state.animView!==state.view;state.animView=state.view;content.classList.toggle("enter",animate);if(state.view==="home")renderStudent(content);if(state.view==="notifications")renderNotifications(content);if(state.view==="queue")renderQueue(content);if(state.view==="settings")renderSettings(content);if(state.view==="models")renderModels(content);decorate(content,animate);}
function renderStudent(content){const open=state.requests.filter(r=>r.status!=="Resolved").length;const completed=state.requests.filter(r=>r.status==="Resolved").length;content.innerHTML=`<div class="page-head"><div><div class="eyebrow">Student workspace</div><h1>How can we help?</h1><p class="muted">You describe the issue. We’ll find the team that can help you.</p></div><span class="pill">Student portal</span></div>${studentIdentity()}${aiBanner()}<div class="stats"><div class="stat"><div class="stat-label">Total requests</div><div class="stat-value">${state.requests.length}</div><div class="stat-foot">All your support conversations</div></div><div class="stat"><div class="stat-label">Open requests</div><div class="stat-value">${open}</div><div class="stat-foot">With a team or awaiting review</div></div><div class="stat"><div class="stat-label">Resolved</div><div class="stat-value">${completed}</div><div class="stat-foot">Support completed</div></div></div><div class="two-col"><section class="card"><div class="card-head"><h2>Send a new request</h2></div><p class="form-hint">Tell us what happened and what you need. ${state.ai.provider==="gemini"?"The AI suggests a route; a support officer handles unclear requests.":"Write in English for automatic routing; other requests go to staff for review."}</p><form id="request-form"><div class="field"><label for="request-title">Subject</label><input id="request-title" name="title" required minlength="3" maxlength="120" placeholder="A short description of your issue"></div><div class="field"><label for="request-message">Your request</label><textarea id="request-message" name="message" required minlength="10" maxlength="4000" placeholder="For example: I cannot connect my laptop to campus Wi-Fi, and my portal password needs to be reset."></textarea></div><div class="field"><label for="request-priority">Priority (set by you)</label><select id="request-priority" name="priority"><option value="normal">Normal</option><option value="urgent">Urgent</option></select></div><div id="request-error" class="error" role="alert" hidden></div><div class="submit-bottom"><button class="btn" type="submit">Send request <span aria-hidden="true">↗</span></button><span class="quiet-tag">Confirmation in your notifications</span></div></form>${state.ai.provider==="gemini"&&state.ai.configured?'<p class="small-text muted">Your request text is sent to Gemini for routing. Keep passwords and payment card details out of your message.</p>':""}<div class="notice">If the route is unclear, a support officer reviews your request. For immediate danger, contact emergency services directly.</div></section><section class="card"><div class="card-head"><h2>${state.sprint===2?"My requests":"Submitted requests"}</h2><span class="quiet-tag">${state.sprint===2?"Refreshes every 15 seconds":"Routing receipts"}</span></div><div class="request-list">${state.requests.length?state.requests.map(studentCard).join(""):emptyRequests()}</div></section></div>`;}
function studentCard(r){return `<article class="request-card${r.priority==="urgent"?" urgent":""}"><div class="request-top"><span class="request-ref">${esc(r.reference)}</span><div class="badge-row">${badge(r)}</div></div><div class="request-title">${esc(r.title)}</div><p class="request-message">${esc(r.message.slice(0,160))}${r.message.length>160?"…":""}</p><div class="request-meta"><span>${esc(r.department_name||"Staff review queue")}</span><span>Updated ${date(r.updated_at)}</span></div><div class="request-bottom"><span class="quiet-tag">${r.status!=="Resolved"&&r.classification?.urgency?.detected?"Urgent: the team was alerted immediately":r.status==="Escalated"?"A person will review your route":r.status==="Resolved"?"Resolution available":"Your request reached the team"}</span><button class="text-btn small-text" data-action="detail" data-id="${r.id}">View request${r.message_count?` · ${r.message_count} message${r.message_count>1?"s":""}`:""}</button></div></article>`;}
function renderNotifications(content){content.innerHTML=`<div class="page-head"><div><div class="eyebrow">Stay informed</div><h1>Notifications</h1><p class="muted">Routing confirmations and updates from your campus teams.</p></div></div><section class="card">${state.notifications.length?state.notifications.map(n=>`<article class="notification ${n.read_at?"read":""}"><div class="notification-dot" aria-hidden="true"></div><div class="notification-text"><p>${esc(n.message)}</p><span class="small-text muted">${date(n.created_at)}</span></div>${n.read_at?"":`<button class="text-btn small-text" data-action="read" data-id="${n.id}">Mark read</button>`}</article>`).join(""):emptyNotifications()}</section>`;}
function renderQueue(content){const f=state.filters;const review=state.requests.filter(r=>r.status==="Escalated").length;content.innerHTML=`<div class="page-head"><div><div class="eyebrow">Support workspace</div><h1>Every request, a clear next step.</h1><p class="muted">Review uncertain routes, connect students to a team, and track progress.</p></div><span class="pill">Support portal</span></div><div class="stats"><div class="stat"><div class="stat-label">In this view</div><div class="stat-value">${state.requests.length}</div><div class="stat-foot">Urgent first, then oldest</div></div><div class="stat"><div class="stat-label">Awaiting route review</div><div class="stat-value">${review}</div><div class="stat-foot">Review target: 4 business hours</div></div><div class="stat"><div class="stat-label">Marked urgent</div><div class="stat-value">${state.requests.filter(r=>r.priority==="urgent").length}</div><div class="stat-foot">Automatic emergency flag or set by the student</div></div></div><form id="filters-form" class="filters"><div class="field"><label for="filter-status">Status</label><select id="filter-status" name="status"><option value="">All statuses</option>${["Received","In Progress","Escalated","Resolved"].map(v=>`<option ${f.status===v?"selected":""}>${v}</option>`).join("")}</select></div><div class="field"><label for="filter-department">Department</label><select id="filter-department" name="department"><option value="">All departments</option>${departmentOptions(f.department)}</select></div><div class="field"><label for="filter-priority">Priority</label><select id="filter-priority" name="priority"><option value="">All priorities</option><option value="normal" ${f.priority==="normal"?"selected":""}>Normal</option><option value="urgent" ${f.priority==="urgent"?"selected":""}>Urgent</option></select></div><label class="toggle-field"><input type="checkbox" name="open" ${f.open?"checked":""}> Open requests only</label></form><div id="queue-list">${state.requests.length?state.requests.map(queueCard).join(""):'<div class="empty"><strong>No requests match these filters</strong>Change the filters to see more requests.</div>'}</div><p class="footer-note">Status updates reach students automatically. Urgent requests are listed first, then by submission time.</p>`;}
function queueCard(r){const model=r.classification;return `<article class="queue-card${r.priority==="urgent"?" urgent":""}"><div><div class="request-top"><span class="request-ref">${esc(r.reference)} · ${esc(r.student_name)}</span><div class="badge-row">${badge(r)}</div></div><h3 class="request-title">${esc(r.title)}</h3><p class="request-message">${esc(r.message)}</p><div class="request-meta"><span>${esc(r.department_name||"Unassigned · staff review")}</span><span>Submitted ${date(r.created_at)}</span></div>${r.review_due_at?`<p class="small-text ${r.review_overdue?"error":"muted"}">Review ${r.review_overdue?"overdue":"due"}: ${date(r.review_due_at)}</p>`:""}<div class="model-note">AI suggestion: <strong>${esc(state.departments.find(d=>d.code===r.suggested_code)?.name||(r.suggested_code==="review"?"Staff review required":r.suggested_code))}</strong> · Confidence estimate: <strong>${Math.round(r.confidence*100)}%</strong><br>Model: ${esc(model.model_version)}<br>${esc(model.reason)}</div>${urgencyNote(r)}<div class="request-bottom"><button class="text-btn small-text" data-action="detail" data-id="${r.id}">Details and messages${r.message_count?` (${r.message_count})`:""}</button><span class="quiet-tag">Updated ${date(r.updated_at)}</span></div></div><div class="queue-ops"><label for="department-${r.id}">${r.department_code?"Reassign to department":"Choose the correct department"}</label><form class="route-form" data-id="${r.id}"><div class="route-row"><select id="department-${r.id}" name="department_code" aria-label="Department for ${esc(r.reference)}" ${r.status==="Resolved"?"disabled":""}>${departmentOptions(r.department_code||r.suggested_code)}</select><button class="btn" type="submit" ${r.status==="Resolved"?"disabled":""}>Route</button></div></form><div class="queue-status">${r.status==="Received"?`<button class="btn secondary small" data-action="status" data-status="In Progress" data-id="${r.id}">Start work</button>`:""}${r.status==="In Progress"?`<button class="btn secondary small" data-action="resolve" data-id="${r.id}">Resolve request</button>`:""}${r.status==="Resolved"?`<button class="btn secondary small" data-action="status" data-status="In Progress" data-id="${r.id}">Reopen</button>`:""}${r.status==="Escalated"?'<span class="quiet-tag">Route the request before starting work.</span>':""}</div></div></article>`;}
async function renderSettings(content){content.innerHTML='<div class="loading">Loading routing settings...</div>';try{const settings=await api("/api/admin/settings");const result=await api("/api/admin/corrections");if(state.view!=="settings")return;content.innerHTML=`<div class="page-head"><div><div class="eyebrow">Administration</div><h1>Routing settings</h1><p class="muted">Control when a request needs a human review.</p></div><span class="pill">Administrator</span></div><div class="settings-layout"><section class="card"><h2>Confidence threshold</h2><p class="form-hint">Requests below this score enter the staff review queue. Changes apply to new and edited requests.</p><form id="settings-form"><div class="field"><label for="threshold">Minimum score for automatic routing</label><input id="threshold" name="confidence_threshold" type="number" min="0.50" max="0.99" step="0.01" value="${settings.confidence_threshold}" required></div><div id="settings-error" class="error" role="alert" hidden></div><button class="btn" type="submit">Save threshold</button></form><div class="notice">Higher scores send more requests to staff. This score is a model estimate, not a guarantee of correctness.</div></section><section class="card"><h2>Model and staff corrections</h2><div class="notice">${esc(aiDescription(settings.ai))}</div><p class="muted small-text">Model version: ${esc(settings.model_version)}<br>${settings.ai.provider==="gemini"?"Pretrained Gemini model; project data is not used for training.":`Local training examples: ${settings.training_examples}`}<br>${esc(aiLabel(settings.ai))}<br>Staff routing decisions saved: ${result.corrections.length}</p>${result.corrections.length?`<table class="correction-table"><thead><tr><th>Request</th><th>Suggested</th><th>Staff route</th></tr></thead><tbody>${result.corrections.slice(0,20).map(c=>`<tr><td>REQ-${String(c.request_id).padStart(5,"0")}</td><td>${esc(c.original_code)}</td><td>${esc(c.corrected_code)}</td></tr>`).join("")}</tbody></table>`:'<div class="empty"><strong>No staff decisions yet</strong>Manual routing decisions will appear here.</div>'}<p class="footer-note">Correction records are stored for the future retraining pipeline.</p></section></div>`;}catch(error){content.innerHTML=`<p class="error">${esc(error.message)}</p>`;}}

/* ---- US11: student-staff message thread, shown in the request detail dialog ---- */
function msgBadge(r){const n=r.unread_messages||0;return n?`<span class="pill unread" title="Unread messages">${n} new message${n>1?"s":""}</span>`:"";}
function setNavBadge(view,count){const link=document.querySelector(`[data-view="${view}"]`);if(!link)return;let b=link.querySelector(".nav-number");if(count){if(!b){b=document.createElement("span");b.className="nav-number";link.appendChild(b);}b.textContent=count;}else if(b)b.remove();}
function updateNavBadges(){if(!state.user)return;if(state.user.role==="student")setNavBadge("notifications",state.notifications.filter(n=>!n.read_at).length);if(state.user.role==="support")setNavBadge("queue",state.staffUnread);}
const thread={id:null,last:0,timer:null,pending:null,touched:false};
function threadSection(r){const student=state.user.role==="student";return `<section class="thread" data-request="${r.id}" aria-label="Messages about ${esc(r.reference)}"><h3>Messages</h3><div class="thread-list" role="log" aria-live="polite" aria-relevant="additions"><p class="muted small-text thread-loading">Loading messages…</p></div><p class="thread-closed small-text muted" hidden></p><form id="message-form" class="thread-form" data-id="${r.id}"><label for="message-body" class="sr-only">Write a message</label><textarea id="message-body" name="body" maxlength="1000" required placeholder="${student?"Write a reply or add a missing detail…":"Ask the student for the missing detail…"}"></textarea><div class="thread-actions"><span class="quiet-tag" id="message-count">0 / 1000</span><button class="btn small" type="submit">Send</button></div></form></section>`;}
function messageHtml(m){return `<div class="msg ${m.mine?"mine":"theirs"}" data-id="${m.id}"><div class="msg-meta"><strong>${esc(m.sender_name)}</strong><span>${m.sender_role==="support"?"Support":"Student"} · ${date(m.created_at)}</span></div><p>${esc(m.body)}</p></div>`;}
function clientId(body){if(!thread.pending||thread.pending.body!==body)thread.pending={body,id:"c"+Date.now().toString(36)+Math.random().toString(36).slice(2,10)};return thread.pending.id;}
function updateCount(){const field=document.getElementById("message-body"),label=document.getElementById("message-count");if(field&&label)label.textContent=`${field.value.length} / 1000`;}
function applyThread(result,replace){const box=thread.id&&dialog.querySelector(`.thread[data-request="${thread.id}"]`);if(!box)return;const list=box.querySelector(".thread-list");const nearBottom=replace||list.scrollHeight-list.scrollTop-list.clientHeight<60;if(replace)list.innerHTML="";else list.querySelectorAll(".thread-loading,.thread-empty").forEach(el=>{if(result.messages.length)el.remove();});result.messages.forEach(m=>{if(list.querySelector(`[data-id="${m.id}"]`))return;list.insertAdjacentHTML("beforeend",messageHtml(m));thread.last=Math.max(thread.last,m.id);});if(!list.children.length)list.innerHTML='<p class="muted small-text thread-empty">No messages yet. Use this space to clarify details without sending a new request.</p>';if(nearBottom)list.scrollTop=list.scrollHeight;box.querySelector(".thread-form").hidden=!result.open;const closed=box.querySelector(".thread-closed");closed.hidden=result.open;closed.textContent=result.open?"":"This conversation is read-only because the request is resolved. It opens again if the request is reopened.";}
async function loadThread(initial){const id=thread.id;if(!id)return;const result=await api(`/api/requests/${id}/messages?after=${initial?0:thread.last}`);if(thread.id!==id)return;applyThread(result,initial);if(!document.hidden&&(initial||result.messages.some(m=>!m.mine))){thread.touched=true;api(`/api/requests/${id}/messages/read`,"POST",{}).catch(()=>{});}}
function startThread(id){stopThread();thread.id=id;thread.last=0;loadThread(true).catch(error=>toast(error.message));thread.timer=setInterval(()=>{if(!document.hidden)loadThread(false).catch(()=>{});},5000);}
function stopThread(){clearInterval(thread.timer);thread.timer=null;thread.id=null;thread.last=0;thread.pending=null;}
async function refreshAfterThread(){if(!state.user||!thread.touched)return;thread.touched=false;try{await loadData();if(state.user.role==="student"&&state.view==="home"){const list=document.querySelector(".request-list");if(list)list.innerHTML=state.requests.length?state.requests.map(studentCard).join(""):emptyRequests();}if(state.user.role==="support"&&state.view==="queue"){const box=document.getElementById("queue-list");if(box&&!(document.activeElement&&box.contains(document.activeElement)))box.innerHTML=state.requests.map(queueCard).join("");}updateNavBadges();}catch{}}
dialog.addEventListener("close",()=>{stopThread();refreshAfterThread();});
document.addEventListener("input",event=>{if(event.target.id==="message-body")updateCount();});
document.addEventListener("keydown",event=>{if(event.target.id==="message-body"&&event.key==="Enter"&&(event.ctrlKey||event.metaKey)){event.preventDefault();event.target.form.requestSubmit();}});

/* ---- US10: administrator page for model retraining, versions and rollback ---- */
const pct=v=>v==null?"—":(v*100).toFixed(1)+"%";
const SKIPPED={already_in_base_data:"Already in the base training data",overlaps_evaluation_set:"Same text as an evaluation example",not_usable_by_local_model:"Not usable by the local model (for example Russian or Kazakh)",weak_label_held_out:"Reopened label in the validation slice"};
const EVENT_TITLES={baseline:"Baseline model registered",retrain_deployed:"Retrained model deployed",retrain_rejected:"Retrained model rejected",retrain_skipped:"Retraining skipped",retrain_failed:"Retraining failed",rolled_back:"Earlier version restored"};
function eventDetail(e){const d=e.detail;if(e.action==="retrain_deployed"||e.action==="retrain_rejected")return `${pct(d.candidate_accuracy)} for the new model vs ${pct(d.live_accuracy)} for the live model on ${d.validation_size} held-out examples · ${d.new_examples} new examples · ${d.origin}`;if(e.action==="rolled_back")return `${d.from_version||"—"} → ${d.to_version} in ${d.duration_ms} ms`;if(e.action==="baseline")return `${d.training_examples} training examples`+(d.accuracy==null?"":` · ${pct(d.accuracy)} on the evaluation set`);return d.reason||"";}
function modelsHtml(m){const active=m.versions.find(v=>v.status==="active")||{};const d=m.data,s=m.settings;const running=Boolean(m.running);
return `<div class="page-head"><div><div class="eyebrow">Administration</div><h1>Model retraining</h1><p class="muted">Staff routing decisions become training data. A retrained model goes live only if it is at least as accurate as the live model on held-out examples.</p></div><span class="pill">IT administrator</span></div>${m.serving?"":'<div class="notice">Live routing currently uses Gemini, a pretrained model that is not retrained here. The versions below belong to the local model and take effect when AI mode is local.</div>'}<div class="stats"><div class="stat"><div class="stat-label">Live model version</div><div class="stat-value sm" data-testid="live-version">${esc(active.version||"—")}</div><div class="stat-foot">${esc(active.training_examples||0)} training examples</div></div><div class="stat"><div class="stat-label">Accuracy at deployment</div><div class="stat-value sm">${pct(active.accuracy)}</div><div class="stat-foot">${esc(active.validation_size||0)} held-out examples</div></div><div class="stat"><div class="stat-label">New labeled examples</div><div class="stat-value">${d.new_since_live_model}</div><div class="stat-foot">${d.usable} usable of ${d.collected} collected</div></div></div><div class="settings-layout"><section class="card"><h2>Retrain</h2><p class="form-hint">Trains a candidate on the base data plus staff-labeled requests, then compares it with the live model. Routing continues normally while it trains.</p><div class="submit-bottom"><button class="btn" type="button" data-action="retrain" ${running?"disabled":""}>${running?"Retraining…":"Retrain now"}</button><span class="quiet-tag">${s.enabled?(m.next_due_at?`Next scheduled check: ${date(m.next_due_at)}`:"Scheduled"):"Automatic retraining is off"}</span></div><h3 class="section-gap">Schedule</h3><form id="retrain-form"><label class="toggle-field"><input type="checkbox" name="enabled" ${s.enabled?"checked":""}> Retrain automatically</label><div class="field"><label for="interval-days">Days between runs</label><input id="interval-days" name="interval_days" type="number" min="1" max="365" step="1" value="${s.interval_days}" required></div><div class="field"><label for="min-new">New examples needed for a scheduled run</label><input id="min-new" name="min_new_samples" type="number" min="1" max="1000" step="1" value="${s.min_new_samples}" required></div><div id="retrain-error" class="error" role="alert" hidden></div><button class="btn secondary" type="submit">Save schedule</button></form></section><section class="card"><h2>Labeled data</h2><table class="correction-table"><tbody><tr><td>Staff corrections</td><td>${d.by_source.staff_correction}</td></tr><tr><td>Escalation outcomes</td><td>${d.by_source.escalation_outcome}</td></tr><tr><td>Reopened requests</td><td>${d.by_source.reopened}</td></tr><tr><td>Used for training</td><td>${d.training}</td></tr><tr><td>Held out for validation</td><td>${d.validation_held_out} + ${d.evaluation_examples} evaluation examples</td></tr>${Object.entries(d.skipped).map(([k,v])=>`<tr><td>${esc(SKIPPED[k]||k)}</td><td>${v}</td></tr>`).join("")}</tbody></table><p class="footer-note">Counts only. Student names and request text are never shown on this page.</p></section></div><section class="card section-gap"><h2>Model versions</h2><div class="table-scroll"><table class="correction-table"><thead><tr><th>Version</th><th>Status</th><th>Examples</th><th>Accuracy</th><th>Created</th><th></th></tr></thead><tbody>${m.versions.map(v=>`<tr><td>${esc(v.version)}<br><span class="muted small-text">${esc(v.origin)}</span></td><td><span class="pill ${esc(v.status)}">${esc(v.status)}</span></td><td>${v.training_examples}</td><td>${pct(v.accuracy)}${v.previous_accuracy==null?"":`<br><span class="muted small-text">live was ${pct(v.previous_accuracy)}</span>`}</td><td>${date(v.created_at)}</td><td>${v.status==="archived"?`<button class="btn secondary small" type="button" data-action="restore" data-version="${esc(v.version)}">Restore</button>`:""}</td></tr>`).join("")}</tbody></table></div></section><section class="card section-gap"><h2>Activity</h2>${m.events.length?`<div class="timeline">${m.events.map(e=>`<div class="timeline-item"><strong>${esc(EVENT_TITLES[e.action]||e.action)}</strong><p>${esc(eventDetail(e))}</p><span class="quiet-tag">${date(e.created_at)}${e.actor_name?" · "+esc(e.actor_name):""}</span></div>`).join("")}</div>`:'<div class="empty"><strong>No activity yet</strong></div>'}</section>`;}
async function renderModels(content){clearTimeout(state.modelsTimer);if(!state.models)content.innerHTML='<div class="loading">Loading model retraining...</div>';try{const models=await api("/api/admin/retraining");state.models=models;if(state.view!=="models")return;content.innerHTML=modelsHtml(models);decorate(content,false);if(models.running)state.modelsTimer=setTimeout(()=>{const box=document.getElementById("content");const focus=document.activeElement;if(state.view==="models"&&box&&!(focus&&focus.closest&&focus.closest("#retrain-form")))renderModels(box);else if(state.view==="models")state.modelsTimer=setTimeout(()=>renderView(),2000);},2000);}catch(error){content.innerHTML=`<p class="error">${esc(error.message)}</p>`;}}
async function loadData(){if(!state.user)return;state.ai=(await api("/api/ai/status")).ai;state.departments=(await api("/api/departments")).departments;if(state.user.role==="student"){state.requests=(await api("/api/requests")).requests;state.notifications=(await api("/api/notifications")).notifications;}if(state.user.role==="support"&&state.sprint===2){const q=new URLSearchParams();Object.entries(state.filters).forEach(([k,v])=>{if(v)q.set(k,k==="open"?"1":v);});const res=await api("/api/staff/requests?"+q);state.requests=res.requests;const previous=state.staffUnread;state.staffUnread=res.unread_messages||0;if(state.staffReady&&state.staffUnread>previous)toast("New message from a student.");state.staffReady=true;}}
async function refresh(shell=false){await loadData();if(shell)renderShell();else renderView();updateNavBadges();}
async function showDetail(id,mode="detail"){stopThread();const result=await api(`/api/requests/${id}`);const r=result.request;dialog.innerHTML=`<div class="dialog-head"><div><div class="request-ref">${esc(r.reference)}</div><h2 id="dialog-title">${mode==="edit"?"Edit request":mode==="resolve"?"Resolve request":mode==="emergency"?"Report an emergency":esc(r.title)}</h2></div><button class="close" data-action="close-dialog" aria-label="Close dialog">×</button></div>${mode==="edit"?`<form id="edit-form" data-id="${r.id}" data-version="${r.version}"><div class="field"><label for="edit-title">Subject</label><input id="edit-title" name="title" value="${esc(r.title)}" minlength="3" maxlength="120" required></div><div class="field"><label for="edit-message">Your request</label><textarea id="edit-message" name="message" minlength="10" maxlength="4000" required>${esc(r.message)}</textarea></div><div id="dialog-error" class="error" hidden role="alert"></div><button class="btn" type="submit">Save and reroute</button></form>`:mode==="emergency"?emergencyForm(r):mode==="resolve"?`<form id="resolve-form" data-id="${r.id}" data-version="${r.version}"><div class="field"><label for="resolution">Resolution message for the student</label><textarea id="resolution" name="resolution" minlength="5" maxlength="2000" required placeholder="Describe what was done and any next steps."></textarea></div><div id="dialog-error" class="error" hidden role="alert"></div><button class="btn" type="submit">Mark resolved</button></form>`:`<div class="badge-row">${badge(r)}</div>${urgencyNote(r)}<p class="request-message">${esc(r.message)}</p><div class="request-meta"><span>${esc(r.department_name||"Staff review queue")}</span><span>Updated ${date(r.updated_at)}</span></div><div class="model-note"><strong>Routing model: ${esc(r.classification.model_version)}</strong><br>${esc(r.classification.reason)}</div>${r.resolution?`<div class="notice"><strong>Resolution</strong><br>${esc(r.resolution)}</div>`:""}${emergencyButton(r)}<div class="timeline">${result.history.map(e=>`<div class="timeline-item"><strong>${esc(e.status)}</strong><p>${esc(e.detail)}</p><span class="quiet-tag">${date(e.created_at)}</span></div>`).join("")}</div>${threadSection(r)}${state.user.role==="student"&&["Received","Escalated"].includes(r.status)?`<div class="dialog-actions"><button class="btn secondary" data-action="edit" data-id="${r.id}">Edit request</button><button class="btn danger" data-action="delete" data-id="${r.id}" data-version="${r.version}">Delete request</button></div>`:""}`}`;if(!dialog.open)dialog.showModal();if(mode==="detail")startThread(r.id);}
document.addEventListener("click",async event=>{const nav=event.target.closest("[data-view]");if(nav){event.preventDefault();state.view=nav.dataset.view;history.replaceState(null,"",nav.getAttribute("href"));renderShell();return;}const button=event.target.closest("[data-action]");if(!button)return;const action=button.dataset.action;try{if(action==="toggle-auth"){state.register=!state.register;renderAuth();}if(action==="logout"){const result=await api("/api/auth/logout","POST",{});state.user=null;state.csrf=result.csrf_token;state.register=false;state.requests=[];state.notifications=[];dialog.close();history.replaceState(null,"","/");renderAuth();}if(action==="detail")await showDetail(button.dataset.id);if(action==="close-dialog")dialog.close();if(action==="edit")await showDetail(button.dataset.id,"edit");if(action==="emergency")await showDetail(button.dataset.id,"emergency");if(action==="ack-alert"){await api(`/api/staff/alerts/${button.dataset.id}/ack`,"POST",{});await pollAlerts();toast("Alert acknowledged.");}if(action==="resolve")await showDetail(button.dataset.id,"resolve");if(action==="status"){const r=state.requests.find(r=>r.id===Number(button.dataset.id));await api(`/api/requests/${r.id}/status`,"POST",{status:button.dataset.status,version:r.version});await refresh();toast("Status updated. The student has been notified.");}if(action==="delete"){if(!confirm("Delete this request? This removes its history and notifications."))return;await api(`/api/requests/${button.dataset.id}`,"DELETE",{version:Number(button.dataset.version)});dialog.close();await refresh(true);toast("Request deleted.");}if(action==="read"){await api(`/api/notifications/${button.dataset.id}/read`,"POST",{});await refresh(true);}if(action==="retrain"){button.disabled=true;await api("/api/admin/retraining/run","POST",{});toast("Retraining started. Routing keeps working while the new model trains.");renderView();}if(action==="restore"){if(!confirm("Restore this model version? New requests will be routed with it immediately."))return;await api(`/api/admin/models/${button.dataset.version}/activate`,"POST",{});toast("Model version restored.");renderView();}}catch(error){toast(error.message);if(action==="retrain")renderView();}});
document.addEventListener("submit",async event=>{const form=event.target;event.preventDefault();const submit=form.querySelector('button[type="submit"]');const originalButton=submit?.innerHTML;if(submit){submit.disabled=true;if(form.id==="request-form"&&state.ai.provider==="gemini")submit.textContent="AI is routing your request…";}const values=Object.fromEntries(new FormData(form));try{if(form.id==="auth-form"){const result=await api(`/api/auth/${state.register?"register":"login"}`,"POST",values);state.user=result.user;state.csrf=result.csrf_token;state.view=state.user.role==="student"?"home":state.user.role==="support"?"queue":"settings";if(state.sprint===1&&state.user.role!=="student"){toast("Staff and administrator features belong to Sprint 2. Use a student account for Sprint 1.");await api("/api/auth/logout","POST",{});const session=await api("/api/session");state.csrf=session.csrf_token;state.user=null;renderAuth();return;}const intro=routeIntro(state.user,state.register);try{await Promise.all([loadData(),intro.ready]);renderShell();}catch(e){intro.leave(true);throw e;}intro.leave();}if(form.id==="request-form"){const result=await api("/api/requests","POST",values);await refresh(true);toast(result.request.status==="Escalated"?"Request received. A support officer will review its route.":`Request sent to ${result.request.department_name}.`);}if(form.classList.contains("route-form")){const r=state.requests.find(r=>r.id===Number(form.dataset.id));await api(`/api/requests/${r.id}/route`,"POST",{...values,version:r.version});await refresh();toast("Route saved. The student has been notified.");}if(form.id==="edit-form"){await api(`/api/requests/${form.dataset.id}`,"PUT",{...values,version:Number(form.dataset.version)});dialog.close();await refresh(true);toast("Request updated and routed again.");}if(form.id==="resolve-form"){await api(`/api/requests/${form.dataset.id}/status`,"POST",{status:"Resolved",resolution:values.resolution,version:Number(form.dataset.version)});dialog.close();await refresh();toast("Request resolved. The student has been notified.");}if(form.id==="emergency-form"){const body={version:Number(form.dataset.version),note:values.note||""};if(values.department_code)body.department_code=values.department_code;await api(`/api/requests/${form.dataset.id}/emergency`,"POST",body);dialog.close();await refresh(true);toast("Staff have been alerted immediately. If anyone is in danger, call emergency services.");}if(form.id==="message-form"){const result=await api(`/api/requests/${form.dataset.id}/messages`,"POST",{body:values.body,client_id:clientId(values.body)});thread.pending=null;form.reset();updateCount();applyThread({messages:[result.message],open:true},false);thread.touched=true;}if(form.id==="retrain-form"){await api("/api/admin/retraining/settings","PUT",{enabled:form.elements.enabled.checked,interval_days:Number(values.interval_days),min_new_samples:Number(values.min_new_samples)});toast("Retraining schedule saved.");renderView();}if(form.id==="settings-form"){await api("/api/admin/settings","PUT",{confidence_threshold:Number(values.confidence_threshold)});toast("Routing threshold saved.");}}catch(error){const box=form.querySelector('[role="alert"]');if(box){box.textContent=error.message;box.hidden=false;const af=form.closest(".auth-form");if(af){af.classList.remove("shake");void af.offsetWidth;af.classList.add("shake");}}else toast(error.message);}finally{if(submit){submit.disabled=false;submit.innerHTML=originalButton;}}});
document.addEventListener("change",async event=>{if(event.target.closest("#filters-form")){const form=document.getElementById("filters-form");const f=Object.fromEntries(new FormData(form));state.filters={status:f.status,department:f.department,priority:f.priority,open:form.elements.open.checked};try{await refresh();}catch(error){toast(error.message);}}});
async function initialize(){try{const session=await api("/api/session");state.user=session.user;state.csrf=session.csrf_token;state.sprint=session.sprint;state.ai=session.ai;state.university=session.university;if(!state.user){renderAuth();return;}const defaultView=state.user.role==="student"?"home":state.user.role==="support"?"queue":"settings";const requested={"/staff":"queue","/notifications":"notifications","/settings":"settings","/models":"models"}[location.pathname]||defaultView;state.view=navItems().some(n=>n.id===requested)?requested:defaultView;if(state.view!==requested){history.replaceState(null,"","/");toast("This page is available to a different account role.");}await refresh(true);}catch(error){root.innerHTML=`<main class="loading"><p class="error">${esc(error.message)}</p><p>Refresh the page to try again.</p></main>`;}}
setInterval(async()=>{if(!state.user||state.view==="settings"||state.view==="models"||document.hidden)return;const focused=document.activeElement;try{if(state.user.role==="student"){await loadData();if(state.view==="home"){const list=document.querySelector('.request-list');if(list)list.innerHTML=state.requests.length?state.requests.map(studentCard).join(""):emptyRequests();const totals=[state.requests.length,state.requests.filter(r=>r.status!=="Resolved").length,state.requests.filter(r=>r.status==="Resolved").length];document.querySelectorAll('.stat-value').forEach((el,i)=>el.textContent=totals[i]);}else if(!dialog.open)renderView();}else if(!dialog.open&&!(focused&&["INPUT","TEXTAREA","SELECT"].includes(focused.tagName))){await refresh();}updateNavBadges();}catch(error){toast(error.message);}},15000);
initialize();

function urgencyNote(r){const u=r.classification?.urgency;return u&&u.detected?`<div class="urgent-note"><strong>Flagged urgent automatically</strong><br>${esc(u.reason)}</div>`:"";}
function emergencyButton(r){if(r.status==="Resolved"||r.classification?.urgency?.detected||!["student","support"].includes(state.user.role))return "";return `<div class="dialog-actions"><button class="btn danger" data-action="emergency" data-id="${r.id}">This is an emergency</button></div>`;}
function emergencyForm(r){const staff=state.user.role==="support";return `<form id="emergency-form" data-id="${r.id}" data-version="${r.version}"><div class="urgent-note">The responsible team is alerted immediately. If anyone is in immediate danger, call emergency services first.</div><div class="field"><label for="emergency-note">What is happening? (optional)</label><textarea id="emergency-note" name="note" maxlength="500"></textarea></div>${staff?`<div class="field"><label for="emergency-dept">Alert department</label><select id="emergency-dept" name="department_code">${departmentOptions(r.department_code||"health")}</select></div>`:""}<div id="dialog-error" class="error" hidden role="alert"></div><button class="btn danger" type="submit">Alert staff now</button></form>`;}
/* Live urgent alerts. Staff poll every 5 s so a new alert is visible well inside the 30 s target. */
function beep(){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=new C(),o=ctx.createOscillator(),g=ctx.createGain();o.type="square";o.frequency.value=880;g.gain.value=.05;o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.35);setTimeout(()=>ctx.close(),600);}catch{}}
function renderAlerts(){const box=document.getElementById("alert-region");if(!box||!state.user)return;let html="",count=0;
if(state.user.role==="support"){count=state.alerts.length;if(state.alertError)html+='<section class="alert-list"><article class="alert-card overdue"><div class="alert-main"><strong>Live urgent alerts are unavailable</strong><p class="small-text">The connection to the server was lost. Refresh the page; check the queue manually until alerts return.</p></div></article></section>';
if(count)html+=`<section class="alert-list" aria-label="Urgent alerts">${state.alerts.map(a=>`<article class="alert-card${a.overdue?" overdue":""}"><div class="alert-main"><strong>${a.kind==="escalation"?"Missed emergency reported":"Urgent request"} · ${esc(a.reference)} · ${esc(a.department_name)}</strong><p>${esc(a.title)}</p><p class="small-text">${esc(a.reason)} · ${ageText(a.age_seconds)}${a.overdue?" · <strong>Not acknowledged for over 2 minutes</strong>":""}</p></div><div class="alert-actions"><button class="btn small" data-action="detail" data-id="${a.request_id}">Open request</button><button class="btn secondary small" data-action="ack-alert" data-id="${a.id}">Acknowledge</button></div></article>`).join("")}</section>`;}
else if(state.user.role==="admin"&&state.supervisor.length){count=state.supervisor.length;html=`<section class="alert-list" aria-label="Unacknowledged urgent alerts"><article class="alert-card overdue"><div class="alert-main"><strong>${count} urgent alert${count>1?"s":""} not acknowledged for over 2 minutes</strong><p class="small-text">${state.supervisor.map(a=>`${esc(a.reference)} · ${esc(a.department_name)} · ${ageText(a.age_seconds)}`).join("<br>")}</p><p class="small-text">Contact the support team now. Request details are visible to support staff only.</p></div></article></section>`;}
box.innerHTML=html;document.title=count?`(${count}) URGENT · Campus Route`:"Campus Route - Student Support";}
async function pollAlerts(){if(!state.user||state.sprint!==2||state.user.role==="student")return;
if(alertsUser!==state.user.id){alertsUser=state.user.id;knownAlerts=null;}
try{if(state.user.role==="support"){const alerts=(await api("/api/staff/alerts")).alerts;const fresh=knownAlerts===null?[]:alerts.filter(a=>!knownAlerts.has(a.id));knownAlerts=new Set(alerts.map(a=>a.id));state.alerts=alerts;state.alertError=false;renderAlerts();if(fresh.length){beep();toast(`${fresh.length} new urgent alert${fresh.length>1?"s":""}`);const f=document.activeElement;if(!dialog.open&&!(f&&["INPUT","TEXTAREA","SELECT"].includes(f.tagName))){await loadData();if(state.view==="queue")renderView();}}}
else{state.supervisor=(await api("/api/admin/alerts")).alerts;state.alertError=false;renderAlerts();}}
catch{state.alertError=true;renderAlerts();}}
setInterval(pollAlerts,5000);
